    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日从日历读取的阅读或听书日程列表，用于展示动态完成数字和首条日程。",
          "sampleValue": [
            {
              "entityId": "calendar-reading-001",
