              "dtStart": "08:30",
              "dtEnd": "09:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条阅读或听书日程。",
            "sampleValue": {
              "entityId": "calendar-reading-001",
              "title": "晨间听书",
              "dtStart": "08:30",
              "dtEnd": "09:00"
            },
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日历日程唯一标识，用于后续打开日程详情或关联运行时数据。",
                "sampleValue": "calendar-reading-001"
              },
              "title": {
                "type": "string",
                "description": "日历中的阅读或听书日程标题。",
                "sampleValue": "晨间听书"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程使用 HH:MM 展示。",
                "sampleValue": "08:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程使用 HH:MM 展示。",
                "sampleValue": "09:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的日历实心图标，适合表示已完成日程、日程确认和任务打卡状态。"
    }
  ]
}

